import React, { useState } from 'react';

export default function ReturnConfirmModal({ open, refCode, onCancel, onConfirm, loading }) {
  const [note, setNote] = useState('');

  const handleSubmit = () => {
    if (!note.trim()) {
      alert('Please enter a reason for returning this document.');
      return;
    }
    onConfirm(note.trim());
    setNote('');
  };

  if (!open) return null;

  return (
    <div className="modal-overlay" onClick={onCancel}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h3>Return Document</h3>
          <button className="modal-close" onClick={onCancel}>×</button>
        </div>
        <div className="modal-body">
          <p style={{ marginBottom: '16px', color: 'var(--t1)' }}>
            <strong>Ref: {refCode}</strong>
          </p>
          <p style={{ marginBottom: '12px', color: 'var(--t2)', fontSize: '14px' }}>
            Please enter the reason for returning this document:
          </p>
          <textarea
            className="inp"
            style={{ width: '100%', minHeight: '100px', fontFamily: 'monospace', fontSize: '13px', padding: '10px' }}
            placeholder="e.g., Missing signature, Document locked, Page damaged, etc."
            value={note}
            onChange={(e) => setNote(e.target.value)}
            disabled={loading}
          />
        </div>
        <div className="modal-footer">
          <button 
            className="btn btn-outline" 
            onClick={onCancel}
            disabled={loading}
          >
            Cancel
          </button>
          <button 
            className="btn btn-red" 
            onClick={handleSubmit}
            disabled={loading || !note.trim()}
          >
            {loading ? 'Returning...' : 'Return Document'}
          </button>
        </div>
      </div>
    </div>
  );
}
